def quickselect_min(nums, k):
    if len(nums) == 1:
        return nums[0]
    pivot_index = partition(nums, 0, len(nums) - 1, None)
    if k <= pivot_index:
        return quickselect_min(nums[:pivot_index], k)
    elif k > pivot_index + 1:
        return quickselect_min(nums[pivot_index + 1:], k - pivot_index - 1)
    else:
        return nums[pivot_index]

def quickselect_max(nums, k):
