import heapq

def solve(nums, k):
    if k == len(nums): return max(nums)
    s = set(nums)

    value = random.choice(list(s))
    while True:
        count = nums.count(value)
        heap = []
        for v in s:
            if v != value:
                heapq.heappush(heap, (-count, v))
        removed = False
        while heap:
            count, v = heapq.heappop(heap)
            if count > 0:
                if k <= len(nums) - count:
                    return v
                else:
                    k -= count
                    removed = True
            else:
                heapq.heappush(heap, (-count, v))
        if not removed:
            return value
        value = random.choice([v for v in s if v != value])
